 $('#local-concept-save').onclick=async()=>{const b=$('#local-concept-save');b.disabled=true;try{await apiPost('/local/concept-review',{id,audience:rotation.audience,concept_version:d.concept_version,revision:d.revision,decision:$('#local-concept-decision').value,reviewer:$('#local-concept-reviewer').value,reason:$('#local-concept-reason').value,source_reviewed:$('#local-concept-source-reviewed').checked});closeModal();await detail(id,true)}catch(e){$('#modalmsg').textContent=e.message;b.disabled=false}};
