 show(ownerLabel("Who may apply (not proof of personal entitlement)"),d.applicant_evidence);show(ownerLabel("What this funds / useful purpose"),d.benefit_evidence);line(ownerReason(d.benefit_scope));
 line(ownerLabel("Current hook: ")+d.hook.voiceover);line(ownerLabel("Current screen accent: ")+(d.hook.screen_text||'missing'));show(ownerLabel("Hook claim references"),d.hook.evidence);
 line(ownerLabel("Current description: ")+(d.description.text||'missing'));line(ownerLabel("Hook critical changes vs sealed version: ")+(d.hook.critical_changes.critical_fields_changed.join(', ')||ownerLabel("none detected; meaning not verified")));
 if(d.local_model_editorial){const m=d.local_model_editorial;const a=m.analysis||{};line(ownerReason(m.scope));if(a.analysis){line(ownerLabel("Model audience: ")+a.analysis.audience);line(ownerLabel("Model useful angle: ")+a.analysis.benefit);line(ownerLabel("Model limits: ")+(a.analysis.limitations||[]).join('; '));line(ownerLabel("Model topic recommendation: ")+a.analysis.topic_decision+' - '+a.analysis.reason);}for(const candidate of a.candidates||[]){line(ownerLabel("Model candidate ")+candidate.id+': '+candidate.segments.map(s=>s.voiceover).join(' '));for(const field of ['clarity','interest','factual_risks','improvements'])line(ownerLabel(field)+': '+candidate.critique[field]);}line(ownerLabel("Model selection: ")+a.selected_id+' - '+a.selection_reason);line(ownerLabel("Source/semantic and owner review remain required; no approval was inherited."));}
 for(const warning of d.warnings)line(ownerLabel("Needs review: ")+ownerReason(warning));
 if(d.source_revision_pending)line(ownerLabel("Changed source candidates are pending reconciliation."));
