async function localFactAdoption(id,box){
 const d=await api('/local/fact-adoption?id='+encodeURIComponent(id));const panel=document.createElement('details');const title=document.createElement('summary');title.textContent=ownerLabel("Review source changes into a fact version");panel.append(title);const line=text=>{const p=document.createElement('p');p.textContent=text;panel.append(p)};
 line(ownerLabel("Current fact version: ")+(d.fact_version||ownerLabel("sealed original reference"))+ownerLabel(". Fact acceptance never approves the scenario, concept or publication. Manual edits stay unchanged."));
 if(d.fact_version)line(ownerLabel("Script, affected scenes and description require revalidation against this fact version and a new concept approval."));if(d.manifest?.related_claim_scope_resolution_required?.length)line(ownerLabel("Related primary/listing claims still need scope resolution: ")+d.manifest.related_claim_scope_resolution_required.map(x=>x.candidate+' / '+x.retained_claim).join('; '));
 for(const item of d.pending_saves){line(ownerLabel("Interrupted save: ")+item.state+(item.reason?'; '+item.reason:''));if(item.state!=='conflict'){const b=document.createElement('button');b.className='btn';b.textContent=ownerLabel("Recover interrupted fact save");b.onclick=async()=>{b.disabled=true;try{await apiPost('/local/fact-recover',{id,request_key:item.request_key});await detail(id,true)}catch(e){line(e.message);b.disabled=false}};panel.append(b);}}
 const inputs=[];
 for(const c of d.changes){const section=document.createElement('details');const heading=document.createElement('summary');heading.textContent=c.claim_key+ownerLabel(" — scenes: ")+(c.affected_scenes.join(', ')||ownerLabel("no explicit binding"))+ownerLabel("; description: ")+c.description_affected;section.append(heading);const before=document.createElement('p');before.textContent=ownerLabel("Before: ")+(c.before?.statement||'absent');const after=document.createElement('p');after.textContent=ownerLabel("Candidate: ")+(c.after?.statement||'removed/absent');section.append(before,after);for(const proof of c.proofs){const p=document.createElement('p');p.textContent=ownerLabel("Saved evidence: ")+(proof.source_url||ownerLabel("unknown URL"))+ownerLabel("; SHA ")+proof.sha256;section.append(p);}if(c.acceptance_blocker){const p=document.createElement('p');p.textContent=ownerLabel("Acceptance blocked: ")+c.acceptance_blocker;section.append(p);}if(c.last_decision){const p=document.createElement('p');p.textContent=ownerLabel("Saved decision: ")+c.last_decision.decision+'; '+c.last_decision.reason;section.append(p);}
 if(c.related_existing_claims.length){const p=document.createElement('p');p.textContent=ownerLabel("Related prior claims remain: ")+c.related_existing_claims.map(x=>x.key+': '+x.statement).join('; ')+ownerLabel(". Scope/contradiction resolution and script revalidation are still required.");section.append(p);}
 const choice=document.createElement('select');for(const [value,text] of [['unchanged',ownerLabel("No new decision")],['accept',ownerLabel("Accept this saved-evidence fact")],['defer','Defer'],['reject',ownerLabel("Reject this candidate")]]){const o=document.createElement('option');o.value=value;o.textContent=text;if(value==='accept'&&c.acceptance_blocker)o.disabled=true;choice.append(o);}const reason=document.createElement('textarea');reason.maxLength=2000;reason.placeholder=ownerLabel("Reason for this exact change");section.append(choice,reason);inputs.push({c,choice,reason});panel.append(section);}
 if(d.changes.length){const reviewer=document.createElement('input');reviewer.placeholder=ownerLabel("Reviewer");reviewer.maxLength=120;const reason=document.createElement('textarea');reason.maxLength=2000;reason.placeholder=ownerLabel("Reason for this fact review batch");const attest=document.createElement('input');attest.type='checkbox';const label=document.createElement('label');label.append(attest,document.createTextNode(ownerLabel("I reviewed the saved evidence for each accepted change; this is not scenario or live-currentness approval.")));const save=document.createElement('button');save.className='btn';save.textContent=ownerLabel("Save selected fact decisions");let requestKey=null;save.onclick=async()=>{save.disabled=true;requestKey=requestKey||crypto.randomUUID();try{await apiPost('/local/fact-adoption',{id,version:d.version,source_revision:d.source_revision,manual_revision:d.manual_revision,actions:inputs.filter(x=>x.choice.value!=='unchanged').map(x=>({change_id:x.c.change_id,decision:x.choice.value,reason:x.reason.value})),reviewer:reviewer.value,reason:reason.value,evidence_reviewed:attest.checked,request_key:requestKey});await detail(id,true)}catch(e){line(e.message);save.disabled=false}};panel.append(reviewer,reason,label,save);}
 if(!d.changes.length)line(ownerLabel("No unresolved difference against the current fact ledger. This does not establish current source status or scenario approval."));box.append(panel);
}

