 line(ownerLabel("Expanded known-term text budget: ")+d.text_budget.expanded_known_acronym_words+ownerLabel(" words. No audio duration, pronunciation, live currentness or editorial acceptance measured."));
 const exportButton=document.createElement('button');exportButton.className='btn';exportButton.textContent=ownerLabel("Export source proposal DRAFT for review");exportButton.onclick=async()=>{exportButton.disabled=true;try{const receipt=await apiPost('/local/export-track-angle',{id,proposal_version:d.proposal_version});const a=document.createElement('a');a.className='btn';a.textContent=ownerLabel("Download separate source-review DRAFT");a.href='/local-media/'+id+'/track_angle_zip?token='+encodeURIComponent(LOCAL_TOKEN)+'&version='+encodeURIComponent(receipt.proposal_version);a.download='';panel.append(a);line(ownerLabel("Saved as a separate review archive. Requires a new preparation and concept review; no production or publication authorized."))}catch(e){line(e.message)}finally{exportButton.disabled=false}};panel.append(exportButton);box.append(panel);
